import re
import subprocess
import os
from ta_emil_cli_aatrace_parser.aashell_user import execute_aashell_command
from ta_emil_cli_aatrace_parser.aashell_user import get_cell_mapping
from robot.api import logger
from collections import OrderedDict


class TraceCollector(object):
    """
    This class is using for enb trace collecting
    """
    @staticmethod
    def get_platform_info_from_aashell():
        """
            Gather info from AaShell eNB process
            :return: dictionary with aashell mapping result
        """
        mapping_cmd = 'getCellMapping @RROMexe'
        try:
            if 'Process \'RROMexe\' not registered to AaShell' in execute_aashell_command(mapping_cmd):
                # on FSMr4 RROMexe is start on port 15081
                logger.debug('RROMexe not avaliable on port 15007, trying on 15081')
                aashell_gathered_info = get_cell_mapping(aashell_port='15081')
                return aashell_gathered_info
                logger.debug('Result of aashell cmd: {}'.format(aashell_gathered_info))
            else:
                aashell_gathered_info = get_cell_mapping(aashell_port='15007')
                return aashell_gathered_info
                logger.debug('Result of aashell cmd: {}'.format(aashell_gathered_info))
        except:
            raise AaShellUsageError()

    @staticmethod
    def get_hw_platform_type(info_from_aashell):
        """
            Parse info from AaShell result
            :return: cells_core_ids - ['0x120d', '0x120c']
        """
        for cell in list(info_from_aashell.keys()):
            platform = info_from_aashell[cell]['L1PoolType'][0:5]
            return platform

    @staticmethod
    def get_unique_core_id_for_uec(info_from_aashell):
        """
            Parse info from AaShell result
            :return: cells_core_ids - ['0x120d', '0x120c']
        """
        core_list = []
        for cell in list(info_from_aashell.keys()):
            core_list.append(info_from_aashell[cell]['UEC'])
        unique_cell_core_ids = set(core_list)
        return unique_cell_core_ids

    @staticmethod
    def get_hw_platform_and_core_ids_for_uec():
        """
            Gather info about hardware of eNB using AaShell
            :return: platform - 'FSMr3' or 'FSMr4'
            :return: cells_core_ids - ['0x120d', '0x120c']
        """
        platform_data = TraceCollector.get_platform_info_from_aashell()   # TO DO change to only one call for this, add to class scope
        platform = TraceCollector.get_hw_platform_type(platform_data)
        unique_cell_core_ids = TraceCollector.get_unique_core_id_for_uec(platform_data)

        logger.debug('Cell core ids configuration on eNB: {} \nPlatform: {}'.format(unique_cell_core_ids, platform))

        return platform, unique_cell_core_ids

    @staticmethod
    def get_cli_aatrace_process():
        """

        :return:
        """
        cmd = 'lsof -i -n -P | grep cli_aatra | grep 15004'
        ps = subprocess.Popen(cmd, stdout=subprocess.PIPE, shell=True)
        output = ps.stdout.read()
        logger.debug('Check cli_aatrace process with command: {}\nresult: {}'.format(cmd, output))
        return output

    @staticmethod
    def translate_msg_name_to_hex(msg_names, msg_dict):
        """

        :param msg_names:
        :param msg_dict:
        :return:
        """
        msg_list = [x.strip() for x in msg_names.split(',')]
        logger.debug('Messages list to parse: {}'.format(msg_list))

        msg_hex_id_list = []
        for msg in msg_list:
            try:
                msg_hex_id_list.append('0x' + msg_dict[msg]['hex_id'])
            except KeyError:
                raise IncorrectMsgName(msg, list(msg_dict.keys()))

        return list(OrderedDict.fromkeys(msg_hex_id_list))

    @staticmethod
    def generate_cli_filters(msg_names=None, msg_dict=None, msg_hex=None):
        """
            Parse filters to list with proper range format
            :param msg_names:     'UEC_PMI_TICKET_IND_MSG, MAC_USER_SETUP_RESP_MSG, MAC_USER_SETUP_REQ_MSG'
            :param msg_dict:      - dictionary with mapping message names to message hex id
            :param msg_hex:       - '0x42a, 0x2222-0x2223, 0x2221' could not be set when msg_name is set
            :return:            ['0x426a-0x426b', '0x2222-0x2223', '0x2221-0x2222']
        """
        parsed_filter_list = []
        if msg_names and msg_hex:
                raise MsgArgummentError(msg_hex, msg_names)

        if msg_names:
            msg_hex_id_list = TraceCollector.translate_msg_name_to_hex(msg_names, msg_dict)
            parsed_filter_list = TraceCollector.parse_hex_id_filter_list(msg_hex_id_list)
        else:
            msg_hex_id_list = [x.strip() for x in msg_hex.split(',')]
            parsed_filter_list = TraceCollector.parse_hex_id_filter_list_with_ranges(msg_hex_id_list)

        logger.debug('Created filters range list: {}'.format(parsed_filter_list))
        return parsed_filter_list

    @staticmethod
    def parse_node_id_list(node_id_list):
        """

        :param node_id_list:
        :return:
        """
        logger.debug('eNB node_id list to parse: {}'.format(node_id_list))
        node_id = [x.strip() for x in node_id_list.split(',')]
        node_id_list_with_proper_format = []
        for node in node_id:
            node_with_proper_format = re.findall(r'0x[0-9a-fA-F]{4}', node)
            if not node_with_proper_format:
                raise IncorrectNodeFormat(node)
            else:
                node_id_list_with_proper_format.append(node_with_proper_format[0])

        return node_id_list_with_proper_format

    @staticmethod
    def parse_hex_id_filter_list(hex_id_list):
        """

        :param hex_id_list:
        :return:
        """
        logger.debug('Message hex_id list to parse: {}'.format(hex_id_list))
        filter_list = []
        for item in hex_id_list:
            filter_range = TraceCollector.generate_filter_range(item)
            filter_list.append(filter_range.lower())
        return filter_list

    @staticmethod
    def parse_hex_id_filter_list_with_ranges(hex_id_list):
        """

        :param hex_id_list:
        :return:
        """
        logger.debug('Message hex_id list with ranges to parse: {}'.format(hex_id_list))
        filter_list = []
        for item in hex_id_list:
            if '-' in item:
                filter_list += re.findall(r'0x[0-9a-fA-F]{4}\-0x[0-9a-fA-F]{4}', item.lower())
            else:
                filter_range = TraceCollector.generate_filter_range(item)
                filter_list.append(filter_range.lower())
        return filter_list

    @staticmethod
    def generate_filter_range(filter_item):
        """

        :param filter_item:
        :return:
        """
        filter_down = re.findall(r'0x[0-9a-fA-F]{4}', filter_item)
        if not filter_down:
            raise IncorrectFilterFormat()
        filter_up = hex(int(filter_down[0], 16) + 1)
        return filter_down[0] + '-' + filter_up

    @staticmethod
    def check_required_os_resources(trace_output_dir, trace_output_file):
        """

        :param trace_output_dir:
        :param trace_output_file:
        :return:
        """
        if os.path.exists(trace_output_file):
            logger.debug('Old file with trace: {} will be deleted !'.format(trace_output_file))
            os.remove(trace_output_file)
        else:
            if not os.path.isdir(trace_output_dir):
                os.mkdir(trace_output_dir)

    @staticmethod
    def build_cli_aatrace_command(platform, cell_core_ids, trace_output_file, parsed_filters):
        """
            Build cli_aatrace_utility_debug command that will be executed via bash
            :param platform         -  hw version
            :param cell_core_ids    -  on which board tracing should be started
            :param trace_output_file - where save traced bin file
            :param parsed_filters    - list of filters with proper ranges
            :return: cmd  - bash command string to run cli aatrace tool with proper params
        """

        logger.debug('Cmd build:\nplatform: {}\ncell_core_ids: {}\nparsed_filters: {}'.format(platform,
                                                                                              cell_core_ids,
                                                                                              parsed_filters))
        cmd_cli = '/bin/bash -c "/opt/ute/python/bin/cli_aatrace_utility_debian'

        if platform == 'FSMr4':
            cmd_cli += ' -H r4'

        for core in cell_core_ids:
            cmd_cli += ' -n {}'.format(core)
            for filter_item in parsed_filters:
                cmd_cli += ' -e {}'.format(filter_item)

        cmd_cli += ' -o {} -i "'.format(trace_output_file)
        logger.info('Cmd build result: {}'.format(cmd_cli))
        return cmd_cli


class TraceStartError(Exception):
    """
    Exception TraceStartError
    """
    def __init__(self):
        self.value = 'It looks like cli_aatrace procces already exists in system !Please execute ' \
                     'ps -ef | grep cli_aatrace_utility to get more details about started process.' \
                     'For test trace starting purposes all other instances need to be close.'

    def __str__(self):
        return repr(self.value)


class TraceStopError(Exception):
    """
    Exception TraceStopError
    """
    def __init__(self):
        self.value = 'It looks like cli_aatrace procces could not be stop ! Please execute ' \
                     'ps -ef | grep cli_aatrace_utility to get more details about process.'

    def __str__(self):
        return repr(self.value)


class TraceStartAliasError(Exception):
    """
    Exception TraceStartAliasError
    """
    def __init__(self, alias, alias_dict):
        self.value = 'Provided trace alias: {} already used ! Already started trace aliases: {}' \
                     'Please use unique aliases for trace in one test.'.format(alias, alias_dict)

    def __str__(self):
        return repr(self.value)


class TraceStopAliasError(Exception):
    """

    """
    def __init__(self, alias, alias_dict):
        Exception.__init__(self)
        self.value = 'Provided trace alias: {} NOT used in test ! Already started trace aliases: {} ' \
                     'Please start trace with proper alias before stop'.format(alias, alias_dict)

    def __str__(self):
        return repr(self.value)


class IncorrectFilterFormat(Exception):
    """

    """
    def __init__(self):
        Exception.__init__(self)
        self.value = 'Wrong format of \'msg_hex\' argument in start_eNB_trace() method ! Msg_hex should ' \
                     'looks like: \'0x426a\' or \'0x426a, 0x2a0b-0x2aff, 0x2222\''

    def __str__(self):
        return repr(self.value)


class AaShellUsageError(Exception):
    """

    """
    def __init__(self):
        Exception.__init__(self)
        self.value = 'Problem with using AASHELL functionality ! Please check if AASHELL is working correctly on eNB.' \
                     'Try: sshenb; telnet 0 15081 or sshenb; telnet 0 15007'

    def __str__(self):
        return repr(self.value)


class IncorrectMsgName(Exception):
    """

    """
    def __init__(self, msg_name, msg_dict):
        Exception.__init__(self)
        self.value = 'Problem with requested for tracing message: {} Msg name typo or msg is not included in SACK ' \
                     'file. Possible msg names retrived from SACK: {}'.format(msg_name, msg_dict)

    def __str__(self):
        return repr(self.value)


class IncorrectNodeFormat(Exception):
    """

    """
    def __init__(self, node_id):
        Exception.__init__(self)
        self.value = 'Problem with requested for tracing node: {} Please verify provided format of ' \
                     'node_id. Example of proper format: 0x124a, 0x120b'.format(node_id)

    def __str__(self):
        return repr(self.value)


class MsgArgummentError(Exception):
    """

    """
    def __init__(self, msg_hex, msg_name):
        Exception.__init__(self)
        self.value = 'Problem with requested for tracing msg_hex: {} could not be requested together with ' \
                     'msg_name: {} Please choose one format of message'.format(msg_hex, msg_name)

    def __str__(self):
        return repr(self.value)
